from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Base TRMM kernel: right-side triangular matrix-matrix multiply
#   B := alpha * (I + strictly-lower(A)^T) * B
# This mirrors the PolyBench/C reference implementation.
@proc
def kernel_trmm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    for i in seq(0, m):
        for j in seq(0, n):
            for k in seq(i + 1, m):
                B[i, j] += A[k, i] * B[k, j]
            B[i, j] = alpha * B[i, j]


# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------

# Tile size along the N dimension (columns of B).  This constant can be
# tuned to match the target machine's cache hierarchy.
TRMM_N_TILE = 64

# 1. Reorder the outer loops so that we iterate over columns 'j' first and
#    rows 'i' second:
#       original: for i in 0..m    for j in 0..n
#       new:      for j in 0..n    for i in 0..m
#    Different columns are independent, so this improves spatial locality
#    on B and exposes outer parallelism across columns.
trmm_sched = reorder_loops(kernel_trmm, "i j")

# 2. Strip-mine / tile the outer 'j' loop:
#       for j in 0..n
#         ->
#       for jo in 0..n / TRMM_N_TILE
#         for ji in 0..TRMM_N_TILE
#           j = TRMM_N_TILE * jo + ji
#       plus a small tail loop for the remainder columns
#    We use tail="cut", which creates a separate loop for the remainder
#    iterations so that no guards are inserted in the main tiled nest.
trmm_sched = divide_loop(trmm_sched, "j", TRMM_N_TILE, ["jo", "ji"], tail="cut")

